<script module lang="ts">
/**
 * Command.Panel: the search row, the listbox and the status inside the palette, mounted with the panel so each opening starts from an empty query.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/command.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import * as zag from '@zag-js/combobox'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/overlays/command.module.css'
import Kbd from '../structure/Kbd.svelte'
import Skeleton from '../structure/Skeleton.svelte'
import type { CommandItem } from './Command.svelte'

export interface CommandPanelProps {
  items: CommandItem[]
  placeholder: string
  escapeHint: string
  filter: 'contains' | false
  loading: boolean
  emptyMessage: string
  onQueryChange?: (query: string) => void
  onCommand?: () => void
}
</script>

<script lang="ts">
let {
  items,
  placeholder,
  escapeHint,
  filter,
  loading,
  emptyMessage,
  onQueryChange,
  onCommand,
}: CommandPanelProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let query = $state('')
const collator = $derived(new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }))
const needle = $derived(query.normalize('NFC'))
const matches = $derived((item: CommandItem) =>
  ((text: string) =>
    needle === '' ||
    Array.from({ length: Math.max(0, text.length - needle.length + 1) }, (_, at) =>
      text.slice(at, at + needle.length),
    ).some((part) => collator.compare(part, needle) === 0))(
    (item.keywords === undefined
      ? item.label
      : `${item.label} ${item.keywords.join(' ')}`
    ).normalize('NFC'),
  ),
)
const shown = $derived(filter === false ? items : items.filter((item) => matches(item)))
const runs = $derived(
  shown.reduce(
    (into, item) => (
      item.group !== undefined && into.at(-1)?.[0]?.group === item.group
        ? into.at(-1)?.push(item)
        : into.push([item]),
      into
    ),
    [] as CommandItem[][],
  ),
)
const firstEnabled = $derived(shown.find((item) => item.disabled !== true)?.id)
const showEmpty = $derived(!loading && shown.length === 0)
const announcement = $derived(
  loading ? 'Loading commands…' : shown.length === 0 ? emptyMessage : `${shown.length} commands`,
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      collection: zag.collection({
        items: shown,
        itemToValue: (item) => item.id,
        itemToString: (item) => item.label,
        isItemDisabled: (item) => item.disabled === true,
      }),
      open: true,
      disableLayer: true,
      value: [],
      closeOnSelect: false,
      selectionBehavior: 'preserve' as const,
      allowCustomValue: true,
      inputBehavior: 'autohighlight' as const,
      placeholder: placeholder,
      onInputValueChange: (details) => {
        ;((query = details.inputValue), onQueryChange?.(details.inputValue))
      },
      onSelect: (details) => {
        ;(items.find((item) => item.id === details.itemValue)?.onSelect(), onCommand?.())
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const effect1 = () => {
  onQueryChange?.(query)
}
watchEffect(effect1)
const effect2 = () => {
  api.highlightedValue === null && firstEnabled !== undefined && api.setHighlightValue(firstEnabled)
}
watchEffect(effect2, { watch: () => api.highlightedValue ?? firstEnabled })
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.search}
    ><Icon name="search" size="md"
    /><input
      {...attributes(mergeParts(api.getInputProps(), { onKeydown: (event: KeyboardEvent) => { if (event.key === 'Escape') api.setInputValue('') } }))}
      class={styles.input}
      aria-label={placeholder}
    /><Kbd>{escapeHint}</Kbd
  ></div
  ><div class={styles.body} data-dialog-part="body"
    ><ul
      {...attributes(api.getContentProps())}
      class={styles.listbox}
      hidden={undefined}
      aria-labelledby={undefined}
      aria-label="Suggestions"
      >{#each runs as run, at (run.map((item) => item.id).join(' '))
        }{#if run[0]?.group === undefined
          }{#each run as item (`${query}/${item.id}`)
            }<li
              {...attributes(api.getItemProps({ item: item, persistFocus: true }))}
              class={styles.item}
              aria-labelledby={`${uid}-label-${item.id}`}
              >{#if item.icon !== undefined
                }<span class={styles.glyph}><Icon name={item.icon} size="sm" /></span
              >{/if
              }<span class={styles.label} id={`${uid}-label-${item.id}`}>{item.label}</span
              >{#if item.hint !== undefined
                }<span class={styles.hint}><Kbd>{item.hint}</Kbd></span
              >{/if
            }</li
          >{/each
        }{:else
          }<li class={styles.section} role="presentation"
            ><span
              {...attributes(api.getItemGroupLabelProps({ htmlFor: `${at}` }))}
              class={styles.groupLabel}
              >{run[0]?.group
            }</span
            ><ul {...attributes(api.getItemGroupProps({ id: `${at}` }))} class={styles.group}
              >{#each run as item (`${query}/${item.id}`)
                }<li
                  {...attributes(api.getItemProps({ item: item, persistFocus: true }))}
                  class={styles.item}
                  aria-labelledby={`${uid}-label-${item.id}`}
                  >{#if item.icon !== undefined
                    }<span class={styles.glyph}><Icon name={item.icon} size="sm" /></span
                  >{/if
                  }<span class={styles.label} id={`${uid}-label-${item.id}`}>{item.label}</span
                  >{#if item.hint !== undefined
                    }<span class={styles.hint}><Kbd>{item.hint}</Kbd></span
                  >{/if
                }</li
              >{/each
            }</ul
          ></li
        >{/if
      }{/each
    }</ul
    >{#if loading
      }<div class={styles.rows} aria-hidden="true"
        >{#each [0, 1, 2] as skeleton (skeleton)
          }<div class={styles.row}><Skeleton textStep="sm" /></div
        >{/each
      }</div
    >{/if
    }{#if showEmpty}<div class={styles.empty} aria-hidden="true">{emptyMessage}</div>{/if
  }</div
  ><div class={styles.status} role="status" aria-live="polite">{announcement}</div
>{/if
}{@render joined.end?.()}
